package vn.somehouse;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.*;import static org.mockito.ArgumentMatchers.*;import static org.mockito.Mockito.*;import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.autoconfigure.web.servlet.WebMvcTest;import org.springframework.context.annotation.Import;import org.springframework.test.context.bean.override.mockito.MockitoBean;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.test.web.servlet.MockMvc;import org.springframework.http.HttpStatus;import java.util.*;
@WebMvcTest(value=ApiController.class,properties="app.upload-dir=./target/test-uploads") @Import({SecurityConfig.class,ApiErrors.class,RequestIds.class}) class ApiContractTest {
 @Autowired MockMvc mvc;@MockitoBean CatalogService catalog;@MockitoBean SiteService site;@MockitoBean JdbcTemplate db;
 @Test void originalProjectCanBeEmbeddedOnlyByThisSite()throws Exception{mvc.perform(get("/project-pages/oriva-bay-quy-nhon/index.html")).andExpect(status().isOk()).andExpect(header().string("X-Frame-Options","SAMEORIGIN")).andExpect(header().string("Content-Security-Policy",org.hamcrest.Matchers.containsString("frame-ancestors 'self'")));}
 @Test void adminStillCannotBeEmbedded()throws Exception{mvc.perform(get("/api/v1/admin/items")).andExpect(status().isUnauthorized()).andExpect(header().string("X-Frame-Options","DENY")).andExpect(header().string("Content-Security-Policy",org.hamcrest.Matchers.containsString("frame-ancestors 'none'")));}
 @Test void anonymousAdminGetsJson401()throws Exception{mvc.perform(get("/api/v1/admin/items")).andExpect(status().isUnauthorized()).andExpect(jsonPath("$.code").value("UNAUTHENTICATED")).andExpect(header().exists("X-Request-ID"));}
 @Test void adminMutationNeedsCsrf()throws Exception{mvc.perform(delete("/api/v1/admin/items/1?version=0").with(user("admin").roles("ADMIN"))).andExpect(status().isForbidden()).andExpect(jsonPath("$.code").value("CSRF_INVALID"));verifyNoInteractions(catalog);}
 @Test void publicPaginationContract()throws Exception{when(catalog.list(eq("PROPERTY"),anyMap(),eq(false))).thenReturn(new ApiTypes.Page<>(List.of(),0,12,0,0));mvc.perform(get("/api/v1/properties?page=0&size=12")).andExpect(status().isOk()).andExpect(jsonPath("$.total").value(0)).andExpect(jsonPath("$.items").isArray());}
 @Test void missingItemIs404Not500()throws Exception{when(catalog.detail(eq("PROPERTY"),eq("missing"),eq("vi"))).thenThrow(ApiException.missing());mvc.perform(get("/api/v1/properties/missing")).andExpect(status().isNotFound()).andExpect(jsonPath("$.code").value("NOT_FOUND"));}
 @Test void invalidLeadDoesNotReachDatabase()throws Exception{mvc.perform(post("/api/v1/leads").with(csrf()).contentType("application/json").header("Idempotency-Key",UUID.randomUUID()).content("{\"name\":\"\",\"phone\":\"abc\",\"email\":\"bad\",\"purpose\":\"INQUIRY\",\"message\":\"\"}")).andExpect(status().isBadRequest()).andExpect(jsonPath("$.code").value("VALIDATION_ERROR")).andExpect(jsonPath("$.errors.phone").exists());verifyNoInteractions(site);}
 @Test void acceptedLeadReturnsReference()throws Exception{when(site.lead(any(),anyString())).thenReturn(new ApiTypes.LeadReceipt("reference-test","Đã tiếp nhận"));mvc.perform(post("/api/v1/leads").with(csrf()).header("Idempotency-Key",UUID.randomUUID()).contentType("application/json").content("{\"name\":\"Khách thử\",\"phone\":\"0972 158 609\",\"email\":\"test@example.invalid\",\"purpose\":\"CONSIGN\",\"message\":\"Cần tư vấn ký gửi\"}")).andExpect(status().isCreated()).andExpect(jsonPath("$.reference").value("reference-test"));}
 @Test void csrfEndpointReturnsSessionToken()throws Exception{mvc.perform(get("/api/v1/auth/csrf")).andExpect(status().isOk()).andExpect(jsonPath("$.token").isNotEmpty()).andExpect(jsonPath("$.headerName").value("X-CSRF-TOKEN"));}
 @Test void missingAuthenticationIsNotReportedAsLoggedIn()throws Exception{mvc.perform(get("/api/v1/auth/me")).andExpect(status().isOk()).andExpect(jsonPath("$.authenticated").value(false));}
 @Test void publicCannotChangeSettings()throws Exception{mvc.perform(put("/api/v1/admin/settings").with(csrf()).contentType("application/json").content("{}")).andExpect(status().isUnauthorized());}
}
